import React from 'react';
import './Hero.css';
import hand_icon from '../Assets/hand_icon.png';
import arrow_icon from '../Assets/arrow.png';
import hero_image from '../Assets/hero_image.png';

const Hero = () => {
  return (
    <section className='hero'>
      {/* Left Content Side */}
      <div className="hero-content">
        <span className="hero-badge">FRESH OFF THE PRESS</span>
        
        <h1 className="hero-title">
          <div className="hand-greeting">
            <span>new</span>
            <img src={hand_icon} alt="Waving hand" />
          </div>
          <span className="highlight">collections</span>
          <span>for everyone</span>
        </h1>

        <div className="hero-action">
          <button className="cta-button">
            Explore Latest
            <img src={arrow_icon} alt="" aria-hidden="true" />
          </button>
        </div>
      </div>

      {/* Right Image Side */}
      <div className="hero-visual">
        <div className="image-wrapper">
            <img src={hero_image} alt="Showcasing our latest fashion" />
        </div>
      </div>
    </section>
  );
};

export default Hero;
